ee:message.ee:set-payload:
%dw 2.0
output application/xml
var orderNumber = "12345"
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns orq http://www.etb.com.co/orquestador
ns orq1 http://schemas.datacontract.org/2004/07/Orquestador.Contracts.Entidades.Agendamiento
ns tem http://tempuri.org/
---
soapenv#Envelope: {
   soapenv#Header: null,
   soapenv#Body: {
      tem#ActualizarPropiedades: {
         tem#solicitud: {
            orq#Encabezado: {
               orq#Sistema: {
                  orq#IdCorrelacion: correlationId default attributes.headers.'x-correlation-id',
                  orq#Nombre: "Mulesoft"
               }
            },
            orq#DatosSolicitud: {
            	orq#Orden: vars.orderNumber,
               orq#propiedades: payload.updateProperties map ((item, index) -> {
                   orq1#Propiedades: {
                     orq1#Label: item.name,
                     orq1#Value: item.value,
                     orq1#Properties: null
                  }
               })
            }
         }
      }
   }
}
